CREATE TABLE IF NOT EXISTS organization_units(id BIGINT AUTO_INCREMENT PRIMARY KEY,org_id BIGINT NOT NULL,unit_type VARCHAR(20) NOT NULL,name VARCHAR(120) NOT NULL,parent_id BIGINT NULL,active BOOLEAN NOT NULL DEFAULT 1,UNIQUE KEY uk_org_unit(org_id,unit_type,name));
CREATE TABLE IF NOT EXISTS document_sharing(page_id BIGINT PRIMARY KEY,general_access VARCHAR(20) NOT NULL DEFAULT 'ORGANIZATION');
CREATE TABLE IF NOT EXISTS document_shares(page_id BIGINT NOT NULL,user_id BIGINT NOT NULL,permission VARCHAR(10) NOT NULL,PRIMARY KEY(page_id,user_id));
CREATE TABLE IF NOT EXISTS document_comments(id BIGINT AUTO_INCREMENT PRIMARY KEY,page_id BIGINT NOT NULL,org_id BIGINT NOT NULL,author_id BIGINT NOT NULL,content TEXT NOT NULL,resolved BOOLEAN NOT NULL DEFAULT 0,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY ix_document_comments(page_id,id));
CREATE TABLE IF NOT EXISTS ticket_documents(org_id BIGINT NOT NULL,ticket_type VARCHAR(20) NOT NULL,ticket_id BIGINT NOT NULL,document_id BIGINT NOT NULL,linked_by BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(org_id,ticket_type,ticket_id,document_id));
CREATE TABLE IF NOT EXISTS workspace_actors(id BIGINT AUTO_INCREMENT PRIMARY KEY,org_id BIGINT NOT NULL,actor_type VARCHAR(10) NOT NULL,display_name VARCHAR(120) NOT NULL,user_id BIGINT NULL,provider VARCHAR(100) NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',created_by BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY ix_actor_org(org_id,actor_type));
CREATE TABLE IF NOT EXISTS roadmap_initiatives(id BIGINT AUTO_INCREMENT PRIMARY KEY,org_id BIGINT NOT NULL,project_id BIGINT NOT NULL,title VARCHAR(255) NOT NULL,description TEXT NULL,owner_id BIGINT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PLANNED',starts_on DATE NOT NULL,target_on DATE NOT NULL,ticket_refs JSON NOT NULL,created_by BIGINT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY ix_roadmap_project(org_id,project_id,starts_on));
